// Must be called before connection/playback; enforce via global attributes.
if (FUZZ_GET_ATTR_INT_GLOBAL("video_connected") != 0) { /* connected already */ FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT_GLOBAL("playback_active") != 0) { /* playback running */ FUZZ_BAIL(); }
// Generate BOOL toggle
BOOL bRuntimeConfig = ((*FUZZ_PARAM(unsigned int)) & 1) ? TRUE : FALSE;
// Invoke and allow either success or failure (provider may reject in certain states)
HRESULT hr = settings->SetRuntimeConfig(bRuntimeConfig);
(void)hr; // Do not assert; API may fail for implementation-specific reasons
// Each call resets settings to defaults; mark this for downstream stubs
FUZZ_SET_ATTR_INT(settings, "is_default_after_setruntime", 1);

// Choose a valid LAVVideoCodec enumerator [0 .. Codec_VideoNB-1]
unsigned int codec_u = (*FUZZ_PARAM(unsigned int)) % (unsigned int)Codec_VideoNB;
LAVVideoCodec vCodec = (LAVVideoCodec)codec_u;
BOOL enabled = settings->GetFormatConfiguration(vCodec);
// Track last queried codec and state for potential cross-stub usage
FUZZ_SET_ATTR_INT(settings, "last_codec_query", (int)codec_u);
FUZZ_SET_ATTR_INT(settings, "last_codec_query_enabled", enabled ? 1 : 0);

// Valid codec in [0 .. Codec_VideoNB-1]
unsigned int codec_u = (*FUZZ_PARAM(unsigned int)) % (unsigned int)Codec_VideoNB;
LAVVideoCodec vCodec = (LAVVideoCodec)codec_u;
BOOL bEnabled = ((*FUZZ_PARAM(unsigned int)) & 1) ? TRUE : FALSE;
HRESULT hr = settings->SetFormatConfiguration(vCodec, bEnabled);
(void)hr; // Do not assert; implementation may reject certain toggles

// Choose a small, reasonable thread count: 0=Auto, 1=single, 2..32=explicit
DWORD dwNum = (DWORD)((*FUZZ_PARAM(unsigned int)) % 33); // 0..32
HRESULT hr = settings->SetNumThreads(dwNum);
(void)hr;
FUZZ_SET_ATTR_INT(settings, "last_set_threads", (int)dwNum);

DWORD n = settings->GetNumThreads();
// Optionally store for correlation; 0=Auto, 1=single, >1 explicit
FUZZ_SET_ATTR_INT(settings, "last_get_threads", (int)n);

// bStreamAR must be 0,1,2
DWORD bStreamAR = (DWORD)((*FUZZ_PARAM(unsigned int)) % 3); // 0..2
HRESULT hr = settings->SetStreamAR(bStreamAR);
(void)hr;
FUZZ_SET_ATTR_INT(settings, "stream_ar", (int)bStreamAR);

DWORD ar = settings->GetStreamAR();
// Must be one of {0,1,2}
FUZZ_ASSERT(ar <= 2, "GetStreamAR returned invalid value");
FUZZ_SET_ATTR_INT(settings, "stream_ar_read", (int)ar);

// pixFmt: choose a valid format index [0 .. LAVOutPixFmt_NB-1]; exclude -1 (None)
unsigned int fmt_u = (*FUZZ_PARAM(unsigned int)) % (unsigned int)LAVOutPixFmt_NB;
LAVOutPixFmts pixFmt = (LAVOutPixFmts)fmt_u;
BOOL en = settings->GetPixelFormat(pixFmt);
FUZZ_SET_ATTR_INT(settings, "last_pixfmt_query", (int)fmt_u);
FUZZ_SET_ATTR_INT(settings, "last_pixfmt_enabled", en ? 1 : 0);

unsigned int fmt_u = (*FUZZ_PARAM(unsigned int)) % (unsigned int)LAVOutPixFmt_NB;
LAVOutPixFmts pixFmt = (LAVOutPixFmts)fmt_u;
BOOL bEnabled = ((*FUZZ_PARAM(unsigned int)) & 1) ? TRUE : FALSE;
HRESULT hr = settings->SetPixelFormat(pixFmt, bEnabled);
(void)hr;

// dwRange must be 0,1,2
DWORD dwRange = (DWORD)((*FUZZ_PARAM(unsigned int)) % 3);
HRESULT hr = settings->SetRGBOutputRange(dwRange);
(void)hr;
FUZZ_SET_ATTR_INT(settings, "rgb_range", (int)dwRange);

DWORD r = settings->GetRGBOutputRange();
FUZZ_ASSERT(r <= 2, "GetRGBOutputRange returned invalid value");
FUZZ_SET_ATTR_INT(settings, "rgb_range_read", (int)r);

unsigned int u = (*FUZZ_PARAM(unsigned int)) % 3; // Auto, TFF, BFF
LAVDeintFieldOrder order = (LAVDeintFieldOrder)u;
HRESULT hr = settings->SetDeintFieldOrder(order);
(void)hr;
FUZZ_SET_ATTR_INT(settings, "deint_field_order", (int)u);

LAVDeintFieldOrder order = settings->GetDeintFieldOrder();
FUZZ_ASSERT((int)order >= 0 && (int)order <= 2, "GetDeintFieldOrder returned invalid enum");
FUZZ_SET_ATTR_INT(settings, "deint_field_order_read", (int)order);

// Deprecated toggle
BOOL bAggressive = ((*FUZZ_PARAM(unsigned int)) & 1) ? TRUE : FALSE;
HRESULT hr = settings->SetDeintAggressive(bAggressive);
(void)hr;
FUZZ_SET_ATTR_INT(settings, "depr_deint_aggr", bAggressive ? 1 : 0);

// Deprecated toggle
BOOL bForce = ((*FUZZ_PARAM(unsigned int)) & 1) ? TRUE : FALSE;
HRESULT hr = settings->SetDeintForce(bForce);
(void)hr;
FUZZ_SET_ATTR_INT(settings, "depr_deint_force", bForce ? 1 : 0);

unsigned int u = (*FUZZ_PARAM(unsigned int)) % (unsigned int)HWAccel_NB;
LAVHWAccel accel = (LAVHWAccel)u;
DWORD support = settings->CheckHWAccelSupport(accel);
// 0=Unsupported, 1=Supported, 2=Currently running
FUZZ_ASSERT(support <= 2, "CheckHWAccelSupport returned invalid value");
FUZZ_SET_ATTR_INT(settings, "last_hwaccel_checked", (int)u);
FUZZ_SET_ATTR_INT(settings, "last_hwaccel_support", (int)support);

unsigned int u = (*FUZZ_PARAM(unsigned int)) % (unsigned int)HWAccel_NB;
LAVHWAccel accel = (LAVHWAccel)u;
HRESULT hr = settings->SetHWAccel(accel);
(void)hr;
FUZZ_SET_ATTR_INT(settings, "hwaccel_set", (int)u);

LAVHWAccel accel = settings->GetHWAccel();
FUZZ_ASSERT((int)accel >= 0 && (int)accel < (int)HWAccel_NB, "GetHWAccel returned invalid enum");
FUZZ_SET_ATTR_INT(settings, "hwaccel_get", (int)accel);

// Choose a valid hardware-accelerated codec [0 .. HWCodec_NB-1]
unsigned int c_u = (*FUZZ_PARAM(unsigned int)) % (unsigned int)HWCodec_NB;
LAVVideoHWCodec hwc = (LAVVideoHWCodec)c_u;
// Toggle enable/disable
BOOL bEnabled = ((*FUZZ_PARAM(unsigned int)) & 1) ? TRUE : FALSE;
HRESULT hr = settings->SetHWAccelCodec(hwc, bEnabled);
(void)hr;
// Track the last set state for potential correlation
FUZZ_SET_ATTR_INT(settings, "hwaccel_codec_last", (int)c_u);
FUZZ_SET_ATTR_INT(settings, "hwaccel_codec_last_enabled", bEnabled ? 1 : 0);
// Validation: enum constrained to valid range; no ownership changes, settings returned to pool.

// Query a valid hardware-accelerated codec [0 .. HWCodec_NB-1]
unsigned int c_u = (*FUZZ_PARAM(unsigned int)) % (unsigned int)HWCodec_NB;
LAVVideoHWCodec hwc = (LAVVideoHWCodec)c_u;
BOOL enabled = settings->GetHWAccelCodec(hwc);
FUZZ_SET_ATTR_INT(settings, "hwaccel_codec_query", (int)c_u);
