    virtual HRESULT __stdcall ResGet(DWORD i, BSTR *ppName, BSTR *ppDesc, BSTR *ppMime, BYTE **ppData, DWORD *pDataLen, DWORD_PTR *pTag) {
        if (i >= items_.size() || !ppName || !ppDesc || !ppMime || !ppData || !pDataLen || !pTag) return (HRESULT)0x80070057L;
        *ppName = 0; *ppDesc = 0; *ppMime = 0; // do not allocate BSTRs in harness
        *ppData = (BYTE *)(items_[i].data.empty() ? nullptr : (void*)items_[i].data.data());
        *pDataLen = (DWORD)items_[i].data.size();
        *pTag = items_[i].tag;
        return 0; // S_OK
    }
    virtual HRESULT __stdcall ResSet(DWORD i, LPCWSTR pName, LPCWSTR pDesc, LPCWSTR pMime, const BYTE *pData, DWORD len, DWORD_PTR tag) {
        if (i >= items_.size() || !pName || !pDesc || !pMime || (!pData && len != 0)) return (HRESULT)0x80070057L;
        items_[i].name = pName; items_[i].desc = pDesc; items_[i].mime = pMime;
        items_[i].data.assign((const char*)pData, (const char*)pData + len);
        items_[i].tag = tag; return 0;
    }
    virtual HRESULT __stdcall ResAppend(LPCWSTR pName, LPCWSTR pDesc, LPCWSTR pMime, BYTE *pData, DWORD len, DWORD_PTR tag) {
        if (!pName || !pDesc || !pMime || (!pData && len != 0)) return (HRESULT)0x80070057L;
        Entry e; e.name = pName; e.desc = pDesc; e.mime = pMime; e.tag = tag; e.data.assign((const char*)pData, (const char*)pData + len);
        items_.push_back(e); return 0;
    }
    virtual HRESULT __stdcall ResRemoveAt(DWORD i) {
        if (i >= items_.size()) return (HRESULT)0x80070057L;
        items_.erase(items_.begin() + i); return 0;
    }
    virtual HRESULT __stdcall ResRemoveAll(DWORD_PTR tag) {
        // Manual filter to avoid std::remove_if dependency
        std::vector<Entry> kept;
        kept.reserve(items_.size());
        for (size_t idx = 0; idx < items_.size(); ++idx) {
            if (items_[idx].tag != tag) kept.push_back(items_[idx]);
        }
        items_.swap(kept);
        return 0;
    }

private:
