import random
import string
from typing import List

# Generator for an HTTP referrer URL (wide string expected by stub after byte->wchar promotion)
# Our bytes will be consumed by FUZZ_PARAM_STR in the stub to build hostnames and pieces.
# We aim to generate valid-looking, ASCII-safe content that, when sanitized by the stub,
# still exercises different code paths (lengths, characters, subdomains, ports, paths, query, fragments).

SAFE_LABEL_CHARS = string.ascii_letters + string.digits + "-"
SAFE_PATH_CHARS = string.ascii_letters + string.digits + "-._~"  # unreserved
SAFE_QUERY_CHARS = SAFE_PATH_CHARS + "=&"  # simple key/value pairs


def _rand_label(r: random.Random, min_len: int = 1, max_len: int = 20) -> str:
    n = r.randint(min_len, max_len)
    # Ensure label doesn't start or end with '-'
    if n == 1:
        return r.choice(string.ascii_lowercase)
    inner_len = max(0, n - 2)
    start = r.choice(string.ascii_lowercase + string.digits)
    inner = ''.join(r.choice(SAFE_LABEL_CHARS) for _ in range(inner_len))
    end = r.choice(string.ascii_lowercase + string.digits)
    return start + inner + end


def _rand_host(r: random.Random) -> str:
    # Build between 1 and 4 labels plus a public suffix-like ending
    labels: List[str] = []
    num_labels = r.randint(1, 4)
    for _ in range(num_labels):
        labels.append(_rand_label(r))
    # Choose a plausible TLD
    tlds = ["test", "example", "local", "invalid", "com", "net", "org"]
    labels.append(r.choice(tlds))
    return '.'.join(labels)


def _rand_port(r: random.Random) -> str:
    # Sometimes include an explicit port
    if r.random() < 0.35:
        return f":{r.randint(1, 65535)}"
    return ""


def _rand_path_segment(r: random.Random) -> str:
    n = r.randint(0, 16)
    if n == 0:
        return ""
    return ''.join(r.choice(SAFE_PATH_CHARS) for _ in range(n))


def _rand_path(r: random.Random) -> str:
    # 0-5 segments
    segs = [_rand_path_segment(r) for _ in range(r.randint(0, 5))]
    # Ensure leading slash if any content
    path = "/" + "/".join(s for s in segs if s is not None)
    # Occasionally make it just "/"
    if r.random() < 0.2:
        path = "/"
    return path


def _rand_query(r: random.Random) -> str:
    if r.random() < 0.5:
        return ""
    params = []
    for _ in range(r.randint(1, 4)):
        k = ''.join(r.choice(SAFE_PATH_CHARS) for _ in range(r.randint(1, 8)))
        v = ''.join(r.choice(SAFE_QUERY_CHARS) for _ in range(r.randint(0, 12)))
        params.append(f"{k}={v}")
    return "?" + "&".join(params)


def _rand_fragment(r: random.Random) -> str:
    if r.random() < 0.3:
        frag = ''.join(r.choice(SAFE_PATH_CHARS) for _ in range(r.randint(1, 16)))
        return "#" + frag
    return ""


def _rand_scheme(r: random.Random) -> str:
    return r.choice(["http", "https"])


def _build_url(r: random.Random) -> str:
    scheme = _rand_scheme(r)
    host = _rand_host(r)
    port = _rand_port(r)
    path = _rand_path(r)
    query = _rand_query(r)
    frag = _rand_fragment(r)
    return f"{scheme}://{host}{port}{path}{query}{frag}"


def _bias_cases(r: random.Random) -> List[str]:
    # Provide some hand-picked URLs for edge coverage
    return [
        "https://example.test/",
        "http://a.test/",
        "https://very-long-subdomain-name-but-valid.example/test",
        "http://localhost/",
        "https://xn--d1acpjx3f.xn--p1ai/",  # punycode-like
        "http://example.invalid/path?x=1&y=2#frag",
    ]


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose between biased corpus and fresh synthesis
    if r.random() < 0.4:
        url = r.choice(_bias_cases(r))
    else:
        url = _build_url(r)

    # Truncate to stay under size limits when converted to wide; bytes used directly by stub as UTF-8
    if len(url) > 1024:
        url = url[:1024]

    # Return as bytes (UTF-8). The stub will sanitize host/path where necessary.
    return url.encode('utf-8')
